if(typeof require==='function'){var Constants=require('./constants');var Counter=require('./counter');}var TimerCountdownCounter=Counter.subclass();TimerCountdownCounter.fields({_startTime:0,_currentTime:0});TimerCountdownCounter.classMethods({createInitialCounterState:function(id,startTime,currentTime){var fields={_startTime:startTime,_currentTime:currentTime};return Counter.createInitialCounterState(id,Constants.COUNTER_TYPES.TIMER_COUNTDOWN,JSON.stringify(fields));}});TimerCountdownCounter.methods({update:function(deltaTime){this._currentTime=Math.max(0,this._currentTime-deltaTime);},done:function(){return this._currentTime<=0;}});if(typeof module==='object'){module.exports=TimerCountdownCounter;}